import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
drafts = {}


def put(number, xml, reason, review):
    assert number not in drafts
    drafts[number] = dict(proposed_xml=xml.strip(), reason=reason, review_notes=review)


